def combine_genes(self, gene_name, parent1_value, parent2_value, crossover_point, gene_index, total_genes):
    # Use a weighted average of the parent genes based on their fitness
    weight1 = parent1_value['fitness'] if parent1_value['fitness'] is not None else 0
    weight2 = parent2_value['fitness'] if parent2_value['fitness'] is not None else 0
    total_weight = weight1 + weight2

    if total_weight > 0:
        combined_value = (weight1 * parent1_value[gene_name] + weight2 * parent2_value[gene_name]) / total_weight
    else:
        combined_value = random.choice([parent1_value[gene_name], parent2_value[gene_name]])

    # Introduce a small probability of selecting a completely random gene
    if random.random() < 0.1:
        combined_value = random.choice(self.search_space[gene_name])

    return combined_value
